{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-52B5XU/src/address.js","content":"/**
 * Cell-address parsing and column-number conversion, shared by the sheet
 * loader (which rejects malformed addresses outright) and the formula
 * evaluator (which turns an out-of-range address into `#REF!`).
 */

/**
 * Parses a token as a strict cell address: one or two letters followed by
 * one to three digits naming a row of at least 1. Returns `{ col, row }`
 * with `col` upper-cased, or `null` when the token does not qualify.
 */
export function parseStrictAddress(raw) {
  const m = /^([A-Za-z]+)([0-9]+)$/.exec(raw)
  if (!m) return null
  const [, letters, digits] = m
  if (letters.length < 1 || letters.length > 2) return null
  if (digits.length < 1 || digits.length > 3) return null
  const row = parseInt(digits, 10)
  if (row < 1) return null
  return { col: letters.toUpperCase(), row }
}

/** Canonical `COLROW` key for an `{ col, row }` address. */
export function addressKey(addr) {
  return `${addr.col}${addr.row}`
}

/** Converts a column letter string (`A`, `Z`, `AA`, ...) to its 1-based number. */
export function colToNum(letters) {
  let n = 0
  for (const ch of letters) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

/** Converts a 1-based column number back to its letter string. */
export function numToCol(n) {
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

/** Compares two addresses by ascending column, then ascending row. */
export function compareAddresses(a, b) {
  const ca = colToNum(a.col)
  const cb = colToNum(b.col)
  if (ca !== cb) return ca - cb
  return a.row - b.row
}

/**
 * Resolves the two corners of a range (raw address tokens) into every
 * address the rectangle covers, in ascending column and then row order.
 * Returns `null` when either corner is not a valid address.
 */
export function resolveRange(rawFrom, rawTo) {
  const a = parseStrictAddress(rawFrom)
  const b = parseStrictAddress(rawTo)
  if (!a || !b) return null
  const colA = colToNum(a.col)
  const colB = colToNum(b.col)
  const minCol = Math.min(colA, colB)
  const maxCol = Math.max(colA, colB)
  const minRow = Math.min(a.row, b.row)
  const maxRow = Math.max(a.row, b.row)
  const addrs = []
  for (let c = minCol; c <= maxCol; c++) {
    const col = numToCol(c)
    for (let r = minRow; r <= maxRow; r++) addrs.push({ col, row: r })
  }
  return addrs
}
"}

