{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-52B5XU/src/values.js","content":"/**
 * The runtime value model shared by literals and formula evaluation: a
 * value is a number, text, a boolean, or an error token.
 */

export const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

export function numberValue(value) {
  return { type: 'number', value }
}

export function textValue(value) {
  return { type: 'text', value }
}

export function boolValue(value) {
  return { type: 'bool', value }
}

export function errorValue(value) {
  return { type: 'error', value }
}

/** Reads a value as a number for an arithmetic position, per the spec's coercions. */
export function toNumber(v) {
  if (v.type === 'number') return v
  if (v.type === 'bool') return numberValue(v.value ? 1 : 0)
  if (v.type === 'text') return errorValue('#VALUE!')
  return v
}

/** Wraps an arithmetic result, turning a non-finite outcome into `#DIV/0!`. */
export function finiteOrDiv0(n) {
  if (!Number.isFinite(n)) return errorValue('#DIV/0!')
  return numberValue(n)
}

function typeRank(v) {
  if (v.type === 'number') return 0
  if (v.type === 'text') return 1
  return 2 // bool
}

/** Orders two non-error values: numbers < text < booleans, each ordered within its kind. */
export function compareValues(l, r) {
  const rl = typeRank(l)
  const rr = typeRank(r)
  if (rl !== rr) return rl < rr ? -1 : 1
  if (l.type === 'number') return l.value < r.value ? -1 : l.value > r.value ? 1 : 0
  if (l.type === 'text') return l.value < r.value ? -1 : l.value > r.value ? 1 : 0
  const lv = l.value ? 1 : 0
  const rv = r.value ? 1 : 0
  return lv - rv
}

/** Parses non-formula cell content into its literal value. */
export function evalLiteral(text) {
  if (text === '') return numberValue(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(text)) return numberValue(parseFloat(text))
  if (ERROR_TOKENS.has(text)) return errorValue(text)
  return textValue(text)
}

/** Formats a number as JavaScript would print it after rounding to ten significant digits. */
export function formatNumber(n) {
  if (n === 0) return '0'
  return String(Number(n.toPrecision(10)))
}

export function formatValue(v) {
  switch (v.type) {
    case 'number':
      return formatNumber(v.value)
    case 'text':
      return v.value
    case 'bool':
      return v.value ? 'TRUE' : 'FALSE'
    default:
      return v.value
  }
}
"}

