 * Evaluates a sheet's cells, with memoization and cycle detection shared
 * across the whole run.
 */
import { addressKey, parseStrictAddress, resolveRange } from './address.js'
import {
  boolValue,
  compareValues,
  errorValue,
  evalLiteral,
  finiteOrDiv0,
  numberValue,
  toNumber,
} from './values.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const NARY_FUNCS = new Set(['SUM', 'MIN', 'MAX', 'AVG', 'COUNT'])

function applyCmp(op, cmp) {
  switch (op) {
    case '=':
      return cmp === 0
    case '<>':
      return cmp !== 0
    case '<':
      return cmp < 0
    case '<=':
      return cmp <= 0
    case '>':
      return cmp > 0
    case '>=':
      return cmp >= 0
  }
}

/** Creates an evaluator for one sheet, caching each cell's value across calls. */
export function createEvaluator(cells) {
  const cache = new Map()
  const visiting = new Set()
  const stack = []
  const cycled = new Set()

  function evaluateCell(key) {
    if (cache.has(key)) return cache.get(key)
    if (visiting.has(key)) {
      const idx = stack.indexOf(key)
      for (let i = idx; i < stack.length; i++) cycled.add(stack[i])
      return errorValue('#CYCLE!')
    }
    const cell = cells.get(key)
    let result
    if (!cell) {
      result = numberValue(0)
    } else {
      visiting.add(key)
      stack.push(key)
      if (cell.content.startsWith('=')) {
        result = cell.parseError ? errorValue('#ERR!') : evaluateNode(cell.ast)
      } else {
        result = evalLiteral(cell.content)
      }
      stack.pop()
      visiting.delete(key)
    }
    if (cycled.has(key)) result = errorValue('#CYCLE!')
    cache.set(key, result)
    return result
  }

  function evalRef(node) {
    const addr = parseStrictAddress(node.raw)
    if (!addr) return errorValue('#REF!')
    return evaluateCell(addressKey(addr))
  }

  /** Expands argument nodes (ranges included) into a flat, left-to-right value list. */
  function expandArgs(argNodes) {
    const out = []
    for (const a of argNodes) {
      if (a.type === 'range') {
        const addrs = resolveRange(a.from, a.to)
        if (!addrs) {
          out.push(errorValue('#REF!'))
          continue
        }
        for (const addr of addrs) out.push(evaluateCell(addressKey(addr)))
      } else {
        out.push(evaluateNode(a))
      }
    }
    return out
  }

  function evalNary(name, node) {
    if (node.args.length < 1) return errorValue('#ERR!')
    const values = expandArgs(node.args)
    if (name === 'COUNT') {
      for (const v of values) if (v.type === 'error') return v
      return numberValue(values.filter((v) => v.type === 'number').length)
    }
    const nums = []
    for (const v of values) {
      if (v.type === 'error') return v
      const n = toNumber(v)
      if (n.type === 'error') return n
      nums.push(n.value)
    }
    if (name === 'SUM') return finiteOrDiv0(nums.reduce((a, b) => a + b, 0))
    if (name === 'MIN') return finiteOrDiv0(Math.min(...nums))
    if (name === 'MAX') return finiteOrDiv0(Math.max(...nums))
    return finiteOrDiv0(nums.reduce((a, b) => a + b, 0) / nums.length)
  }

  function evalAbs(node) {
    if (node.args.length !== 1) return errorValue('#ERR!')
    const values = expandArgs(node.args)
    if (values.length !== 1) return errorValue('#ERR!')
    const v = values[0]
    if (v.type === 'error') return v
    const n = toNumber(v)
    if (n.type === 'error') return n
    return finiteOrDiv0(Math.abs(n.value))
  }

  function readCondition(v) {
    if (v.type === 'bool') return v
    return toNumber(v)
  }

  function evalIf(node) {
    if (node.args.length !== 3) return errorValue('#ERR!')
    const condValues = expandArgs([node.args[0]])
    if (condValues.length !== 1) return errorValue('#ERR!')
    const cv = condValues[0]
    if (cv.type === 'error') return cv
    const read = readCondition(cv)
    if (read.type === 'error') return read
    const flag = read.type === 'bool' ? read.value : read.value !== 0
    const branch = flag ? node.args[1] : node.args[2]
    const branchValues = expandArgs([branch])
    if (branchValues.length !== 1) return errorValue('#ERR!')
    return branchValues[0]
  }

  function evalCall(node) {
    if (node.name === 'IF') return evalIf(node)
    if (node.name === 'ABS') return evalAbs(node)
    if (NARY_FUNCS.has(node.name)) return evalNary(node.name, node)
    return errorValue('#NAME?')
  }

  function evalArith(op, l, r) {
    if (l.type === 'error') return l
    if (r.type === 'error') return r
    const nl = toNumber(l)
    if (nl.type === 'error') return nl
    const nr = toNumber(r)
    if (nr.type === 'error') return nr
    if ((op === '/') && nr.value === 0) return errorValue('#DIV/0!')
    let result
    switch (op) {
      case '+':
        result = nl.value + nr.value
        break
      case '-':
        result = nl.value - nr.value
        break
      case '*':
        result = nl.value * nr.value
        break
      case '/':
        result = nl.value / nr.value
        break
      case '^':
        result = Math.pow(nl.value, nr.value)
        break
    }
    return finiteOrDiv0(result)
  }

  function evalBinop(node) {
    const l = evaluateNode(node.left)
    const r = evaluateNode(node.right)
    if (COMPARISON_OPS.has(node.op)) {
      if (l.type === 'error') return l
      if (r.type === 'error') return r
      return boolValue(applyCmp(node.op, compareValues(l, r)))
    }
    return evalArith(node.op, l, r)
  }

  function evalUnary(node) {
    const v = evaluateNode(node.expr)
    if (v.type === 'error') return v
    const n = toNumber(v)
    if (n.type === 'error') return n
    return finiteOrDiv0(node.op === '-' ? -n.value : n.value)
  }

  function evaluateNode(node) {
    switch (node.type) {
      case 'number':
        return numberValue(node.value)
      case 'bool':
        return boolValue(node.value)
      case 'ref':
        return evalRef(node)
      case 'call':
        return evalCall(node)
      case 'binop':
        return evalBinop(node)
      case 'unary':
        return evalUnary(node)
    }
  }

  return { evaluateCell }
}
