/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */
import { compareAddresses } from './address.js'
import { collectRefs } from './deps.js'
import { createEvaluator } from './evaluate.js'
import { parseSheet, SheetError } from './sheet.js'
import { formatValue } from './values.js'

function fail(message) {
  process.stderr.write(message + '\n')
  process.exit(2)
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const argv = process.argv.slice(2)
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'values' && mode !== 'deps')) {
    fail('error: usage: cli.js values|deps')
  }

  const input = readStdin()
  let cells
  try {
    cells = parseSheet(input)
  } catch (err) {
    if (err instanceof SheetError) fail(err.message)
    throw err
  }

  const addrs = [...cells.values()].sort(compareAddresses)
  const lines = []

  if (mode === 'values') {
    const evaluator = createEvaluator(cells)
    for (const cell of addrs) {
      const value = evaluator.evaluateCell(cell.key)
      lines.push(`${cell.key}=${formatValue(value)}`)
    }
  } else {
    for (const cell of addrs) {
      const refs = cell.content.startsWith('=') && !cell.parseError ? collectRefs(cell.ast) : []
      const suffix = refs.map((r) => ` ${r.col}${r.row}`).join('')
      lines.push(`${cell.key}:${suffix}`)
    }
  }

  process.stdout.write(lines.length ? lines.join('\n') + '\n' : '')
}

main()
"}

